-- Исследования с таблицами замеров.
--  lessons.research_plan      — шаблон: какие таблицы, строки (варианты), столбцы (заезды), единицы, считать ли среднее
--  research_answers.data      — что ученик вписал в таблицы
-- Курс «Колесо»: исследования в реализуемой версии — тележка-испытатель, горка, сменные оси.
-- Пояснения к опытам — на занятиях; на сайте только названия и таблицы.

alter table public.lessons add column if not exists research_plan jsonb;
alter table public.research_answers add column if not exists data jsonb not null default '{}'::jsonb;
alter table public.research_answers drop constraint if exists research_answers_data_size;
alter table public.research_answers add constraint research_answers_data_size check (length(data::text) <= 20000);

update public.lessons l set research_task = v.task, research_plan = v.plan::jsonb
from (values
  (1, 1, 'Круглые, шестиугольные и квадратные колёса', $j${"tables":[
    {"title":"Дальность с горки","unit":"см","rows":["Круглые","Шестиугольные","Квадратные"],"cols":["Заезд 1","Заезд 2","Заезд 3"],"avg":true},
    {"title":"Монета на тележке","rows":["Круглые","Шестиугольные","Квадратные"],"cols":[{"n":"Заезд 1","text":true},{"n":"Заезд 2","text":true},{"n":"Заезд 3","text":true}]}]}$j$),
  (2, 1, 'Тащить или катить: сколько грузиков нужно, чтобы сдвинуть тележку', $j${"tables":[
    {"title":"Грузиков до начала движения","unit":"шт.","rows":["Стол — колёса заблокированы","Стол — колёса крутятся","Ковёр — колёса заблокированы","Ковёр — колёса крутятся"],"cols":["Попытка 1","Попытка 2","Попытка 3"],"avg":true,"addRows":true}]}$j$),
  (2, 3, 'Узкие и широкие колёса на гладком полу и на крупе', $j${"tables":[
    {"title":"Дальность по гладкому полу","unit":"см","rows":["Узкие колёса","Широкие колёса"],"cols":["Заезд 1","Заезд 2","Заезд 3"],"avg":true},
    {"title":"Дальность по крупе","unit":"см","rows":["Узкие колёса","Широкие колёса"],"cols":["Заезд 1","Заезд 2","Заезд 3"],"avg":true}]}$j$),
  (2, 4, 'Три двигателя без мотора: горка, резиномотор, воздушный шарик', $j${"tables":[
    {"title":"Дальность","unit":"см","rows":["Горка — 1 книга","Горка — 2 книги","Горка — 3 книги","Резиномотор","Воздушный шарик"],"cols":["Заезд 1","Заезд 2","Заезд 3"],"avg":true,"addRows":true}]}$j$),
  (2, 6, 'Маленькие, средние и большие колёса: дальность и «порог»', $j${"tables":[
    {"title":"Дальность с горки","unit":"см","rows":["Маленькие колёса","Средние колёса","Большие колёса"],"cols":["Заезд 1","Заезд 2","Заезд 3"],"avg":true},
    {"title":"Переехали порог? (да / нет)","rows":["Маленькие колёса","Средние колёса","Большие колёса"],"cols":[{"n":"Карандаш","text":true},{"n":"Книга","text":true},{"n":"Свой порог","text":true}]}]}$j$),
  (2, 7, 'Гладкие колёса, шины из резинки, изолента: сцепление', $j${"tables":[
    {"title":"Высота края доски, когда тележка поехала","unit":"см","rows":["Гладкие колёса","Шины из резинки","Изолента"],"cols":["Попытка 1","Попытка 2","Попытка 3"],"avg":true,"addRows":true}]}$j$),
  (4, 2, 'Надёжность крепления колеса: сколько ударов выдержит', $j${"tables":[
    {"title":"Удары до поломки","rows":["Пластилин","Термоклей","Скотч"],"cols":["Ударов",{"n":"Что сломалось","text":true}],"addRows":true}]}$j$),
  (5, 2, 'Парус и форма носа: как воздух тормозит тележку', $j${"tables":[
    {"title":"Дальность с горки","unit":"см","rows":["Без паруса","С парусом"],"cols":["Заезд 1","Заезд 2","Заезд 3"],"avg":true},
    {"title":"Откат от фена","unit":"см","rows":["Плоский щит","Клин","Конус"],"cols":["Попытка 1","Попытка 2","Попытка 3"],"avg":true}]}$j$),
  (5, 3, 'Ворот: тонкий и толстый барабан', $j${"tables":[
    {"title":"Подъём груза на 30 см","rows":["Тонкий барабан","Толстый барабан"],"cols":["Оборотов ручки","Сколько монет поднял"],"addRows":true}]}$j$),
  (6, 1, 'Краш-тест: бампер и пассажир', $j${"tables":[
    {"title":"Как далеко улетел пассажир","unit":"см","rows":["Горка — 1 книга","Горка — 2 книги","Горка — 3 книги","Горка — 4 книги"],"cols":["Без бампера","С бампером"],"addRows":true}]}$j$)
) as v(module_sort, lesson_sort, task, plan),
  public.modules m, public.courses c
where c.slug = 'wheel' and m.course_id = c.id and m.sort = v.module_sort
  and l.module_id = m.id and l.sort = v.lesson_sort;
